int rock_ridge_continue(struct rock_state *rs) {
    if (!rs || rs->offset >= rs->block_size || rs->size > rs->block_size - rs->offset) {
        return -1;
    }

    void *buffer = malloc(rs->size);
    if (!buffer) {
        return -1;
    }

    if (read_extent(rs->extent, rs->offset, buffer, rs->size) < 0) {
        free(buffer);
        return -1;
    }

    rs->offset += rs->size;
    rs->buffer = buffer;
    rs->remaining = rs->size;

